import React, { useRef, useEffect, useState, useCallback } from "react";
import {
  certs,
  degrees,
  monthLabel,
  year,
  thumb,
  maskSrc,
  img,
  credSlug,
  certBySlug,
  appliedCount,
  recentCount,
  heroCerts,
  ISSUER_LOGOS,
  ISSUER_LOGO_SCALE,
  ISSUER_LOGO_ASPECT,
  ISSUER_ACCENTS,
  ISSUER_NEEDS_NAME,
  accentFor,
} from "../eduData";
