/** Distinct issuers, newest credential first — the credibility strip. */
const issuers = (() => {
  const seen = [];
  certs.forEach((c) => {
    if (!seen.includes(c.issuer)) seen.push(c.issuer);
  });
  return seen;
})();


const SITE_URL = "https://laxman824.github.io";

/** Full-resolution certificate viewer. Esc / backdrop / arrows all work. */
function Lightbox({ index, onClose, onStep }) {
  const c = certs[index];
  const closeRef = useRef(null);

  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") onClose();
      else if (e.key === "ArrowRight") onStep(1);
      else if (e.key === "ArrowLeft") onStep(-1);
    };
    window.addEventListener("keydown", onKey);
    // the page behind must not scroll while this is open
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    if (closeRef.current) closeRef.current.focus();
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [onClose, onStep]);

  if (!c) return null;
  const full = img(c.image); // originals, not the display thumbnails

  return (
    <div
      className="lb"
      role="dialog"
      aria-modal="true"
      aria-label={`${c.title} — ${c.issuer}`}
      onClick={onClose}
    >
      <div className="lb-inner" onClick={(e) => e.stopPropagation()}>
        <button
          type="button"
          className="lb-close"
          onClick={onClose}
          ref={closeRef}
          aria-label="Close"
        >
          ✕
        </button>

        <button
          type="button"
          className="lb-nav lb-prev"
          onClick={() => onStep(-1)}
          aria-label="Previous certificate"
        >
          ‹
        </button>
        <button
          type="button"
          className="lb-nav lb-next"
          onClick={() => onStep(1)}
          aria-label="Next certificate"
        >
          ›
        </button>

        <figure className="lb-figure" style={{ "--ca": accentFor(c.issuer) }}>
          {full && (
            <img
              key={c.image}
              src={full}
              alt={`${c.title} certificate issued by ${c.issuer}`}
            />
          )}
        </figure>

        <div className="lb-meta" style={{ "--ca": accentFor(c.issuer) }}>
          <div className="lb-meta-main">
            <p className="lb-issuer">
              {c.issuer} <i>·</i> {monthLabel(c.date)}
            </p>
            <h3 className="lb-title">{c.title}</h3>
            {c.credentialId && <p className="lb-cred">{c.credentialId}</p>}
          </div>
          <div className="lb-actions">
            {c.appliedIn && (
              <a className="lb-btn" href={`/projects/${c.appliedIn.slug}`}>
                {c.appliedIn.label} →
              </a>
            )}
            {c.verifyUrl && (
              <a
                className="lb-btn is-verify"
                href={c.verifyUrl}
                target="_blank"
                rel="noopener noreferrer"
              >
                Verify with {c.issuer} ↗
              </a>
            )}
          </div>
          <p className="lb-count">
            {index + 1} / {certs.length}
          </p>
        </div>
      </div>
    </div>
  );
}

/** Rolls 0 -> value the first time it scrolls into view. */
function CountUp({ value, suffix = "", duration = 1400 }) {
  const [n, setN] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let raf;
    const run = () => {
      const t0 = performance.now();
      const tick = (t) => {
        const p = Math.min(1, (t - t0) / duration);
        const e = 1 - Math.pow(1 - p, 4); // easeOutQuart
        setN(Math.round(e * value));
        if (p < 1) raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    };
    if (typeof IntersectionObserver === "undefined") {
      setN(value);
      return;
    }
    const obs = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          run();
          obs.disconnect();
        }
      },
      { threshold: 0.5 }
    );
    obs.observe(el);
    return () => {
      obs.disconnect();
      if (raf) cancelAnimationFrame(raf);
    };
  }, [value, duration]);
  return (
    <span ref={ref}>
      {n}
      {suffix}
    </span>
  );
}

/** Credential id with a copy affordance. */
function CredentialId({ id }) {
  const [copied, setCopied] = useState(false);
  if (!id) return null;
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(id);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch (e) {
      /* clipboard blocked — the id is still selectable on screen */
    }
  };
  return (
    <button
      type="button"
      className={`sk-cred${copied ? " is-copied" : ""}`}
      onClick={copy}
      title="Copy credential ID"
    >
      <span className="sk-cred-label">Credential ID</span>
      <span className="sk-cred-val">{id}</span>
      <span className="sk-cred-act">{copied ? "Copied ✓" : "Copy"}</span>
    </button>
  );
}

function StackEdu({ theme }) {
  const cardRefs = useRef([]);
  const degRefs = useRef([]);
  const headRef = useRef(null);
  const fanRef = useRef(null);
  const [fanAt, setFanAt] = useState(0);
  const [fanPaused, setFanPaused] = useState(false);
  const [lightbox, setLightbox] = useState(null);
  const [copied, setCopied] = useState(null);

  const stepLightbox = useCallback(
    (d) =>
      setLightbox((i) =>
        i === null ? i : (i + d + certs.length) % certs.length
      ),
    []
  );

  /* Cursor-following spotlight, matching the home page's expertise deck. */
  const onSpot = useCallback((e) => {
    if (window.innerWidth < 769) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const el = e.currentTarget;
    const r = el.getBoundingClientRect();
    el.style.setProperty(
      "--mx",
      `${(((e.clientX - r.left) / r.width) * 100).toFixed(1)}%`
    );
    el.style.setProperty(
      "--my",
      `${(((e.clientY - r.top) / r.height) * 100).toFixed(1)}%`
    );
  }, []);

  const copyLink = useCallback((slug) => {
    const url = `${window.location.origin}/education#${slug}`;
    navigator.clipboard.writeText(url).then(
      () => {
        setCopied(slug);
        setTimeout(() => setCopied(null), 1600);
      },
      () => {}
    );
  }, []);

  // the hero deck deals itself: front card slides back, the rest advance
  useEffect(() => {
    if (fanPaused) return undefined;
    const t = setInterval(() => setFanAt((v) => (v + 1) % heroCerts.length), 2600);
    return () => clearInterval(t);
  }, [fanPaused]);

  useEffect(() => {
    let raf = null;
    let ticking = false;

    const update = () => {
      ticking = false;
      const vh = window.innerHeight;

      cardRefs.current.forEach((el) => {
        if (!el) return;
        const r = el.getBoundingClientRect();
        const stickTop = parseFloat(el.dataset.stick || "0");
        const past = Math.max(0, stickTop - r.top);
        el.style.setProperty(
          "--depth",
          Math.min(1, past / (vh * 0.55)).toFixed(4)
        );
        el.style.setProperty(
          "--enter",
          Math.min(1, Math.max(0, (vh - r.top) / (vh * 0.55))).toFixed(4)
        );
      });

      degRefs.current.forEach((el) => {
        if (!el) return;
        const r = el.getBoundingClientRect();
        el.style.setProperty(
          "--enter",
          Math.min(1, Math.max(0, (vh - r.top) / (vh * 0.7))).toFixed(4)
        );
      });

      if (headRef.current) {
        const r = headRef.current.getBoundingClientRect();
        const out = Math.min(1, Math.max(0, -r.top / (vh * 0.8)));
        headRef.current.style.setProperty("--out", out.toFixed(4));
        if (fanRef.current)
          fanRef.current.style.setProperty("--fan", out.toFixed(4));
      }
    };

    const onScroll = () => {
      if (!ticking) {
        ticking = true;
        raf = requestAnimationFrame(update);
      }
    };

    // the fan tilts toward the cursor, and a soft spotlight tracks it
    let pending = false;
    let px = 0;
    let py = 0;
    const paint = () => {
      pending = false;
      if (fanRef.current) {
        fanRef.current.style.setProperty(
          "--mx",
          (px / window.innerWidth - 0.5).toFixed(3)
        );
        fanRef.current.style.setProperty(
          "--my",
          (py / window.innerHeight - 0.5).toFixed(3)
        );
      }
    };
    const onMove = (e) => {
      px = e.clientX;
      py = e.clientY;
      if (!pending) {
        pending = true;
        requestAnimationFrame(paint);
      }
    };

    update();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    window.addEventListener("mousemove", onMove);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      window.removeEventListener("mousemove", onMove);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);


  /* ---------------------------------------- deep link to one credential */
  useEffect(() => {
    const open = () => {
      const slug = decodeURIComponent(window.location.hash.replace(/^#/, ""));
      if (!slug) return false;
      const c = certBySlug(slug);
      if (!c) return false;
      // window.scrollTo is a no-op sitewide (html/body use overflow-x: clip),
      // so nudge scrollTop directly, then open the certificate outright.
      const el = document.getElementById(slug);
      if (el) {
        document.documentElement.scrollTop =
          el.getBoundingClientRect().top +
          document.documentElement.scrollTop -
          140;
      }
      setLightbox(certs.indexOf(c));
      return true;
    };

    // The router rewrites the URL on mount, so the hash can land a tick late.
    open();
    const retry = setTimeout(open, 500);
    window.addEventListener("hashchange", open);
    return () => {
      clearTimeout(retry);
      window.removeEventListener("hashchange", open);
    };
  }, []);

  /* ------------------------------------------------- credential schema */
  useEffect(() => {
    let node = document.getElementById("credentials-jsonld");
    if (!node) {
      node = document.createElement("script");
      node.type = "application/ld+json";
      node.id = "credentials-jsonld";
      document.head.appendChild(node);
    }
    node.textContent = JSON.stringify({
      "@context": "https://schema.org",
      // same @id as the Person in index.html, so consumers merge the nodes
      "@id": `${SITE_URL}/#person`,
      "@type": "Person",
      name: "K Laxman",
      url: `${SITE_URL}/education`,
      alumniOf: degrees.map((d) => ({
        "@type": "CollegeOrUniversity",
        name: "Indian Institute of Technology Delhi",
        alternateName: "IIT Delhi",
        url: d.link,
      })),
      hasCredential: [
        ...degrees.map((d) => ({
          "@type": "EducationalOccupationalCredential",
          name: d.degree,
          credentialCategory: "degree",
          educationalLevel: d.short === "M.Tech" ? "Master's Degree" : "Bachelor's Degree",
          dateCreated: d.end,
          recognizedBy: {
            "@type": "CollegeOrUniversity",
            name: "Indian Institute of Technology Delhi",
            url: d.link,
          },
        })),
        ...certs.map((c) => ({
          "@type": "EducationalOccupationalCredential",
          name: c.title,
          credentialCategory: "certificate",
          dateCreated: c.date,
          identifier: c.credentialId || undefined,
          url: `${SITE_URL}/education#${credSlug(c)}`,
          ...(c.verifyUrl ? { sameAs: c.verifyUrl } : {}),
          competencyRequired: (c.skills || []).join(", ") || undefined,
          recognizedBy: { "@type": "Organization", name: c.issuer },
        })),
      ],
    });
    return () => {
      const n = document.getElementById("credentials-jsonld");
      if (n) n.remove();
    };
  }, []);

  return (
    <div
      className={`sk is-${theme.name === "light" ? "light" : "dark"}`}
      style={{
        "--fg": theme.text,
        "--muted": theme.secondaryText,
        "--accent": theme.accentColor,
        "--accent2": theme.accentBright,
        "--bg": theme.body,
      }}
    >
      {/* ========================================================= hero */}
      <section className="sk-hero">
      <header className="sk-head" ref={headRef}>
        <div className="sk-head-text">
          <p className="sk-eyebrow">
            <i />
            Education &amp; credentials
          </p>

          {/* one line per section of the page: degrees, credentials, proof */}
          <h1 className="sk-title">
            Qualified at <span className="hl">IIT&nbsp;Delhi.</span>
            <br />
            Certified ever since.
            <br />
            <span className="dim">Proven in production.</span>
          </h1>

          {/* the headline now carries the production claim, so the lede
              pivots to verifiability rather than repeating it */}
          <p className="sk-lede">
            Two computer science degrees, then {certs.length} credentials
            earned since. Every one carries an ID you can check with the
            issuer yourself — nothing on this page asks to be taken on trust.
          </p>

          <div className="sk-facts">
            <p>
              <b>
                <CountUp value={certs.length} />
              </b>
              <span>credentials</span>
            </p>
            <p>
              <b>
                <CountUp value={recentCount} />
              </b>
              <span>this year</span>
            </p>
            <p>
              <b>
                <CountUp value={appliedCount} />
              </b>
              <span>shipped into products</span>
            </p>
            <p>
              <b>
                <CountUp value={100} suffix="%" />
              </b>
              <span>independently verifiable</span>
            </p>
          </div>

          <p className="sk-cue">
            Scroll — they stack up <i>↓</i>
          </p>
        </div>

        {/* fanned preview of the deck below */}
        <div
          className="sk-fan"
          ref={fanRef}
          aria-hidden="true"
          onMouseEnter={() => setFanPaused(true)}
          onMouseLeave={() => setFanPaused(false)}
        >
          {heroCerts.map((c, i) => {
            const src = thumb(c.image);
            const slot = (i - fanAt + heroCerts.length) % heroCerts.length;
            // only five slots are on stage; the rest park behind slot 5
            const shown = Math.min(slot, 5);
            return (
              <div
                className={`sk-fan-card${
                  c.imageFit === "logo" ? " is-logo" : ""
                }${slot > 4 ? " is-off" : ""}`}
                key={c.title + c.date}
                style={{ "--i": shown, zIndex: 20 - shown }}
              >
                {src && <img src={src} alt="" />}
              </div>
            );
          })}
          <div className="sk-fan-dots">
            {heroCerts.map((c, i) => (
              <span
                key={c.title + c.date}
                className={i === fanAt ? "is-on" : ""}
              />
            ))}
          </div>
        </div>
      </header>

      {/* issuers — proof at a glance, on a continuous rail */}
      <div className="sk-issuers">
        <span className="sk-issuers-label">Issued by</span>
        <div className="sk-marquee">
          {/* the list is rendered twice so translateX(-50%) loops seamlessly */}
          <div className="sk-marquee-track">
          {[...issuers, ...issuers].map((n, idx) => {
            const logo = ISSUER_LOGOS[n] ? maskSrc(ISSUER_LOGOS[n]) : null;
            return (
              <span
                className="sk-issuer-logo"
                key={`${n}-${idx}`}
                aria-hidden={idx >= issuers.length}
                style={{ "--brand": ISSUER_ACCENTS[n] || "var(--fg)" }}
              >
                <span className="sk-issuer-mark-wrap">
                  {logo ? (
                    /* masked, not <img> — lets one silhouette tint to the
                       brand's own colour on hover regardless of source art */
                    <span
                      className="sk-issuer-mask"
                      role="img"
                      aria-label={n}
                      style={{
                        WebkitMaskImage: `url(${logo})`,
                        maskImage: `url(${logo})`,
                        height: `${26 * (ISSUER_LOGO_SCALE[n] || 1)}px`,
                        width: `${
                          26 *
                          (ISSUER_LOGO_SCALE[n] || 1) *
                          (ISSUER_LOGO_ASPECT[n] || 3)
                        }px`,
                      }}
                    />
                  ) : (
                    <b>{n}</b>
                  )}
                </span>
                {ISSUER_NEEDS_NAME.has(n) && (
                  <span className="sk-issuer-name">{n}</span>
                )}
              </span>
            );
          })}
          </div>
        </div>
      </div>
      </section>

      {/* ==================================================== plaques */}
      <section className="sk-plaques">
        <p className="sk-section">The foundation</p>
        {degrees.map((d, i) => (
          <article
            className="sk-plaque"
            key={d.degree}
            style={{ "--pa": d.accent }}
            onMouseMove={onSpot}
            ref={(el) => {
              degRefs.current[i] = el;
            }}
          >
            <span className="sk-spot" aria-hidden="true" />
            <img className="sk-watermark" src={thumb(d.logo)} alt="" />
            <div className="sk-plaque-in">
              <div className="sk-seal-col">
                <img className="sk-seal" src={thumb(d.logo)} alt="IIT Delhi" />
                <span className="sk-seal-tag">{d.short}</span>
              </div>
              <div className="sk-plaque-text">
                <h2 className="sk-plaque-inst">
                  Indian Institute of Technology
                </h2>
                <h3 className="sk-plaque-city">Delhi</h3>
                <div className="sk-plaque-rule" />
                <p className="sk-plaque-sub">{d.degree}</p>
                <p className="sk-plaque-year">{d.duration}</p>
                <ul className="sk-plaque-points">
                  {d.bullets.map((b) => (
                    <li key={b}>{b}</li>
                  ))}
                </ul>
              </div>
            </div>
          </article>
        ))}
      </section>

      {/* ====================================================== stack */}
      <div className="sk-stack-head">
        <p className="sk-section">The credentials</p>
        <div className="sk-stack-head-row">
          <h2>
            {certs.length} of them.
            <br />
            <span>Newest first.</span>
          </h2>
          <p className="sk-stack-note">
            Each one stacks on the last — scroll and the pile builds, with
            every card underneath still showing its edge. Click any
            certificate to read it full size.
          </p>
        </div>
      </div>

      <section className="sk-stack">
        {certs.map((c, i) => {
          const stick = 108 + i * 16;
          const src = thumb(c.image);
          const logo = ISSUER_LOGOS[c.issuer]
            ? maskSrc(ISSUER_LOGOS[c.issuer])
            : null;
          return (
            <article
              className="sk-card"
              id={credSlug(c)}
              key={c.title + c.date}
              data-stick={stick}
              ref={(el) => {
                cardRefs.current[i] = el;
              }}
              style={{
                top: `${stick}px`,
                zIndex: i + 1,
                "--ca": accentFor(c.issuer),
              }}
            >
              <div className="sk-card-in" onMouseMove={onSpot}>
                <span className="sk-spot" aria-hidden="true" />
                {/* full-width header — this strip is what stays visible as
                    later cards stack on top, so it carries the identity */}
                <header className="sk-card-top">
                  <span className="sk-issuer">
                    {logo && (
                      <img className="sk-issuer-mark" src={logo} alt="" />
                    )}
                    {c.issuer}
                    <i>·</i>
                    {monthLabel(c.date)}
                  </span>
                  <span className="sk-no">
                    {String(certs.length - i).padStart(2, "0")}
                    <em>/{certs.length}</em>
                  </span>
                </header>

                <div className="sk-card-body">
                {/* outlined ghost numeral, same device the home page uses */}
                <span className="sk-ghost" aria-hidden="true">
                  {year(c.date)}
                </span>
                <button
                  type="button"
                  className="sk-shot"
                  onClick={() => setLightbox(i)}
                  aria-label={`View the ${c.title} certificate full size`}
                >
                  {src && (
                    <img
                      src={src}
                      alt={c.title}
                      className={c.imageFit === "logo" ? "is-logo" : ""}
                      loading="lazy"
                      decoding="async"
                    />
                  )}
                  <span className="sk-shot-zoom">
                    <svg viewBox="0 0 24 24" aria-hidden="true">
                      <circle
                        cx="11"
                        cy="11"
                        r="6.5"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1.8"
                      />
                      <path
                        d="M15.8 15.8 21 21M11 8.6v4.8M8.6 11h4.8"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1.8"
                        strokeLinecap="round"
                      />
                    </svg>
                    View full size
                  </span>
                </button>

                <div className="sk-info">
                  <h3 className="sk-name">{c.title}</h3>

                  <div className="sk-skills">
                    {(c.skills || []).map((s) => (
                      <span key={s}>{s}</span>
                    ))}
                  </div>

                  {/* ------------------ credential → production */}
                  {c.appliedIn ? (
                    <a
                      className="sk-applied"
                      href={`/projects/${c.appliedIn.slug}`}
                    >
                      <span className="sk-applied-head">
                        <i className="sk-applied-dot" />
                        Where this went into production
                      </span>

                      <span className="sk-applied-flow">
                        <span className="sk-applied-from">
                          {c.issuer} credential
                        </span>
                        <span className="sk-applied-arrow">
                          <b />
                        </span>
                        <span className="sk-applied-to">
                          {c.appliedIn.label}
                        </span>
                      </span>

                      {c.appliedIn.note && (
                        <span className="sk-applied-note">
                          {c.appliedIn.note}
                        </span>
                      )}

                      <span className="sk-applied-cta">
                        Open the case study
                        <em>→</em>
                      </span>
                    </a>
                  ) : (
                    <p className="sk-applied-none">
                      Foundational — not tied to a single shipped project.
                    </p>
                  )}

                  {/* ------------------------- verification block */}
                  <div className="sk-verify-block">
                    <CredentialId id={c.credentialId} />
                    {c.verifyUrl ? (
                      <a
                        className="sk-verify"
                        href={c.verifyUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <svg viewBox="0 0 24 24" aria-hidden="true">
                          <path
                            d="M12 2.5 4.5 5.8v5.4c0 4.6 3.2 8.9 7.5 10.3 4.3-1.4 7.5-5.7 7.5-10.3V5.8L12 2.5Z"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="1.6"
                            strokeLinejoin="round"
                          />
                          <path
                            d="m8.6 11.9 2.3 2.3 4.5-4.6"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="1.9"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                          />
                        </svg>
                        <span>
                          Verify with <strong>{c.issuer}</strong>
                        </span>
                        <em>↗</em>
                      </a>
                    ) : (
                      <span className="sk-verify is-none">
                        Certificate on file
                      </span>
                    )}
                    <button
                      type="button"
                      className={`sk-link${
                        copied === credSlug(c) ? " is-copied" : ""
                      }`}
                      onClick={() => copyLink(credSlug(c))}
                      title="Copy a direct link to this credential"
                    >
                      {copied === credSlug(c) ? "Link copied ✓" : "🔗 Link"}
                    </button>
                  </div>
                </div>
                </div>
              </div>
            </article>
          );
        })}
      </section>

      {lightbox !== null && (
        <Lightbox
          index={lightbox}
          onClose={() => setLightbox(null)}
          onStep={stepLightbox}
        />
      )}

      <footer className="sk-end">
        <p>
          Every credential above links straight to its issuer for
          verification. The newest is {monthLabel(certs[0].date)} — and this
          list is still growing.
        </p>
        <a href="/projects">See what they built →</a>
      </footer>
    </div>
  );
}

export default StackEdu;
