import { credentials } from "../../portfolio";

export const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

/** "2026-08" -> 2026.583 — sortable, plottable. */
export function toFloat(ym) {
  const [y, m] = ym.split("-").map(Number);
  return y + (m - 1) / 12;
}

export function monthLabel(ym) {
  const [y, m] = ym.split("-").map(Number);
  return `${MONTHS[m - 1]} ${y}`;
}

export function year(ym) {
  return Number(ym.split("-")[0]);
}

/**
 * Display-sized WebP variant (generated alongside each source image).
 * Falls back to the original if a variant was never produced.
 * Use `img()` when the full-resolution file is genuinely needed.
 */
export function thumb(name) {
  const base = name.replace(/\.[^.]+$/, "");
  try {
    return require(`../../assests/images/${base}-sm.webp`);
  } catch (e) {
    return img(name);
  }
}

/**
 * Resized copy of an issuer logo for CSS mask-image. Kept as PNG rather than
 * WebP because mask-image + WebP is unreliable in older Safari.
 */
export function maskSrc(name) {
  const base = name.replace(/\.[^.]+$/, "");
  try {
    return require(`../../assests/images/${base}-mask.png`);
  } catch (e) {
    return img(name);
  }
}

export function img(name) {
  try {
    return require(`../../assests/images/${name}`);
  } catch (e) {
    return null;
  }
}

/** Newest first — the order every variant shows them in. */
export const certs = [...credentials.certificates].sort(
  (a, b) => toFloat(b.date) - toFloat(a.date)
);

export const degrees = credentials.degrees;

/** Short machine-ish handle used by the transcript variant. */
export function handle(c) {
  return c.title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .split("-")
    .slice(0, 3)
    .join("-");
}

export const recentCount = (() => {
  const newest = Math.max(...certs.map((c) => toFloat(c.date)));
  return certs.filter((c) => toFloat(c.date) > newest - 1).length;
})();

export const appliedCount = certs.filter((c) => c.appliedIn).length;

