/**
 * The hero deck only shows real certificate artwork. Entries whose `image`
 * is just the issuer's logo (imageFit: "logo") are skipped — a logo tile
 * reads as a placeholder next to a scanned certificate. Supply a real
 * certificate image and drop `imageFit` and it joins the deck automatically.
 */
export const heroCerts = certs.filter((c) => c.imageFit !== "logo");

/* ------------------------------------------------------------------ slugs */

const slugify = (v) =>
  v
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

/**
 * Stable per-credential anchor. Titles alone collide (two "Certified
 * Professional Back-End Developer", two "Software Engineering Virtual
 * Experience"), so colliding ones get their issuer prefixed.
 */
export const certSlugs = (() => {
  const counts = new Map();
  certs.forEach((c) => {
    const t = slugify(c.title);
    counts.set(t, (counts.get(t) || 0) + 1);
  });
  const map = new Map();
  certs.forEach((c) => {
    const t = slugify(c.title);
    map.set(c, counts.get(t) > 1 ? `${slugify(c.issuer)}-${t}` : t);
  });
  return map;
})();

export const credSlug = (c) => certSlugs.get(c);

export const certBySlug = (slug) =>
  certs.find((c) => certSlugs.get(c) === slug);
